[CALL:write_file]{"path": "index.html", "content": "<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>P5.js Interactivo</title>
    <link rel="stylesheet" href="style.css">
    <!-- Incluir la librería p5.js -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.4.0/p5.js"></script>
</head>
<body>
    <!-- El canvas se creará y manejará enteramente por p5.js -->
    <script src="script.js"></script>
</body>
</html>"}

// satisfy [CALL:write_file]
[CALL:write_file]{"path": "style.css", "content": "body {
    margin: 0;
    padding: 0;
    overflow: hidden; /* Asegura que el canvas ocupe todo el viewport */
    background-color: #111; /* Fondo oscuro para contraste */\}"}

// satisfy [CALL:write_file]
