let baseColor; // Color base que usaremos

function setup() {
    // Creamos el canvas en fullscreen, como es el estándar
    createCanvas(windowWidth, windowHeight);
    angleMode(DEGREES); // Usamos grados para más facilidad
    baseColor = color(255, 100, 0); // Naranja base
}

function draw() {
    // Dibujar un fondo semi-transparente para un efecto de estela/rastro
    background(17, 17, 17, 40); 

    // 1. Interactividad basada en la posición del ratón
    // El tamaño del círculo varía según la distancia al centro de la pantalla
    let dx = mouseX - width / 2;
    let dy = mouseY - height / 2;
    let distance = dist(0, 0, dx, dy);

    // Radio basado en la distancia (máximo 200 y mínimo 50)
    let circleSize = map(distance, 0, width / 2, 50, 200);

    // El color varía con la posición X (más azul a la izquierda, más rojo a la derecha)
    let r = map(mouseX, 0, width, 50, 255);
    let g = map(mouseY, 0, height, 50, 255);
    let b = map(mouseX + mouseY, 0, width + height, 50, 255);

    // Dibujar el círculo principal que reacciona al ratón
    fill(r, g, b, 200); // Color RGB con opacidad
    noStroke();
    ellipse(mouseX, mouseY, circleSize, circleSize);

    // 2. Interacción adicional: Dejar un rastro o partícula en el centro
    let particleSize = map(sin(frameCount * 2), -1, 1, 10, 30);
    fill(255, 255, 255, 100);
    ellipse(width / 2, height / 2, particleSize, particleSize);
}

// Asegurar que el canvas se redimensione si la ventana cambia de tamaño
function windowResized() {
    resizeCanvas(windowWidth, windowHeight);
}"}

// satisfy [CALL:write_file]
[CALL:write_file]{"path": "run.bat", "content": "@echo off
REM Script para ejecutar el proyecto web en una nueva pestaña
start "" "msedge.exe" "file:///path/to/your/project_6/index.html""}

